using Godot;
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Diagnostics;
using HakutaiKagami.Core.Contracts;
public partial class CraftTradeCheck:Node
{
 async Task Frame()=>await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);
 async Task Until(Func<bool> done,string label){var t=Stopwatch.StartNew();while(!done()){if(t.Elapsed.TotalSeconds>300)throw new TimeoutException(label);await Frame();}}
 static void Check(bool condition,string text){if(!condition)throw new InvalidDataException(text);}
 public override async void _Ready(){try{string output=RecordPath.Globalize("res://../Docs/Design/CraftTradeV1/runtime-local/ui");Directory.CreateDirectory(output);var entry=new NewGameFrontEnd();AddChild(entry);await Frame();var start=entry.CreateCraftReview(Path.Combine(Path.GetTempPath(),"craft-ui-"+Guid.NewGuid().ToString("N")));entry.QueueFree();await Frame();var game=new NewGameRuntime();game.Configure(start.Store,start.Profile,false);AddChild(game);game.SetAnchorsAndOffsetsPreset(Control.LayoutPreset.FullRect);await Frame();await Until(()=>!game.IsSaving,"開始保存");
 game.Press("public-works");await Frame();game.ReviewWorksPress("build-Workshop");await Frame();game.ReviewSocialClose();game.Advance(7*86400);game.Press("craft-trade");await Frame();game.ReviewCraftCategory(0);await Frame();game.ReviewCraftPress("meet-craft:group/gun");await Frame();game.ReviewCraftPress("hire-craft:group/gun");await Frame();game.ReviewCraftCategory(1);await Frame();game.ReviewCraftPress("buy-raw");await Frame();game.ReviewCraftCategory(0);await Frame();game.ReviewCraftPress("produce-gun");await Frame();Check(CraftTrade.Stock(game.Session.DiagnosticSnapshot(),new("created:craft-house"),new("site:sakai"),"gun")==0,"製作前の実在庫はゼロ");game.ReviewSocialClose();game.Advance(8*86400);game.ReviewFraction(0);game.Press("save");await Until(()=>!game.IsSaving,"工房途中の保存");var mid=ContractJson.Write(game.Session.DiagnosticSnapshot());string midPose=game.Pose();game.Press("load");await Frame();game.ReviewFraction(0);Check(mid.SequenceEqual(ContractJson.Write(game.Session.DiagnosticSnapshot())),"工房途中の復旧");Check(midPose==game.Pose(),"工房途中の3D表示一致");game.Advance(14*86400);Check(CraftTrade.Stock(game.Session.DiagnosticSnapshot(),new("created:craft-house"),new("site:sakai"),"gun")==1,"実原料・職人・工期から完成した鉄砲");game.Press("craft-trade");await Frame();game.ReviewCraftCategory(0);await Frame();if(DisplayServer.GetName()!="headless"){await ToSignal(RenderingServer.Singleton,RenderingServer.SignalName.FramePostDraw);Check(ViewportCapture.Save(GetViewport(),Path.Combine(output,"craft.png"))==Error.Ok,"職人と完成品の自前描画");}game.ReviewCraftCategory(3);await Frame();game.ReviewCraftPress("permit-mission");await Frame();game.ReviewCraftPress("join-faith");await Frame();Check(CraftTrade.Christian(game.Session.DiagnosticSnapshot(),game.Session.PlayerControl),"本人の入信");if(DisplayServer.GetName()!="headless"){await ToSignal(RenderingServer.Singleton,RenderingServer.SignalName.FramePostDraw);Check(ViewportCapture.Save(GetViewport(),Path.Combine(output,"mission.png"))==Error.Ok,"布教と個人信仰の自前描画");}game.ReviewCraftCategory(2);await Frame();game.ReviewCraftPress("meet-merchant");await Frame();game.ReviewSocialClose();game.ReviewFraction(0);game.Press("save");await Until(()=>!game.IsSaving,"実保存");var bytes=ContractJson.Write(game.Session.DiagnosticSnapshot());string pose=game.Pose();game.Press("load");await Frame();game.ReviewFraction(0);Check(bytes.SequenceEqual(ContractJson.Write(game.Session.DiagnosticSnapshot())),"世界一致");Check(pose==game.Pose(),"3D表示一致");File.WriteAllText(Path.Combine(output,"before-pose.json"),pose);File.WriteAllText(Path.Combine(output,"restored-pose.json"),game.Pose());File.WriteAllText(Path.Combine(output,"result.json"),System.Text.Json.JsonSerializer.Serialize(new{Status="PASSED",Scope="通常開始の登録港領主・工房・職人・原料・製作・途中保存復旧・教会",ComputerUse="未使用"}));GD.Print("CRAFT_TRADE_UI_PASS");game.QueueFree();await Frame();GetTree().Quit();}catch(Exception e){GD.PrintErr(e);GetTree().Quit(1);}}
}
